<div class="card"><div class="card-header"><h3 class="card-title">Fila de pagamento</h3></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Documento / Parcela</th><th>Fornecedor</th><th>Empenho</th><th>Valor da parcela</th><th>CMDF</th><th>Status</th><th style="min-width:360px">Pagamento</th></tr></thead><tbody><?php foreach($pagamentos as $p):?><tr><td><a href="/documentos/<?=e($p['documento_id'])?>"><strong><?=e($p['tipo_documento'])?> <?=e($p['documento_numero'])?></strong></a><div class="small text-body-secondary">Parcela <?=e($p['numero_parcela'])?></div></td><td><?=e($p['fornecedor'])?></td><td><?=e($p['empenho_numero'])?>/<?=e($p['empenho_ano'])?></td><td class="money"><?=money($p['valor_total'])?></td><td><?=e($p['data_cmdf'])?></td><td><span class="badge <?=$p['status']==='PAGO'?'text-bg-success':'text-bg-warning'?>"><?=e($p['status'])?></span></td><td><?php if($p['status']!=='PAGO'):?><form method="post" action="/documentos/<?=e($p['documento_id'])?>/parcelas/<?=e($p['parcela_id'])?>/pagar" class="row g-1"><div class="col-4"><input type="date" name="data_pagamento" value="<?=date('Y-m-d')?>" class="form-control form-control-sm" required></div><div class="col-3"><input name="valor_liquido_pago" class="form-control form-control-sm" placeholder="Valor líquido"></div><div class="col-3"><input name="benner_ap" class="form-control form-control-sm" placeholder="Benner AP"></div><div class="col-2"><button class="btn btn-success btn-sm w-100">Pagar</button></div><div class="col-12 mt-1"><input name="historico_pagamento" class="form-control form-control-sm" placeholder="Histórico do pagamento"></div></form><?php else:?><div><strong><?=e($p['data_pagamento'])?></strong> · <?=money($p['valor_liquido_pago'])?></div><div class="small text-body-secondary"><?=e($p['benner_ap'])?></div><?php endif;?></td></tr><?php endforeach;?><?php if(!$pagamentos):?><tr><td colspan="7" class="text-center text-body-secondary py-4">Nenhuma parcela liberada pela CMDF para pagamento.</td></tr><?php endif;?></tbody></table></div></div>